function designerPaperChoice(mode,layout){let sizes=mode==='thermal'?[{id:'58',name:'Thermal 58 mm',width:58},{id:'80',name:'Thermal 80 mm',width:80}]:invoicePaperSizes;let match=sizes.find(p=>Math.abs(p.width-layout.width)<0.2&&(mode==='thermal'||Math.abs(p.height-layout.height)<0.2));return `<label class="field designerPaperField"><span>Paper Size</span><select data-designer-paper="${mode}" aria-label="Designer paper size">${opts(sizes.map(p=>({value:p.id,label:p.name+(p.dimensions?' ('+p.dimensions+')':'')})),match?.id||(mode==='thermal'?'80':supportedInvoicePaper(db.settings.invoicePaperSize)))}</select></label>`}
const defaultTemplateBeforePaperSync=defaultTemplate;
defaultTemplate=function(mode){let t=defaultTemplateBeforePaperSync(mode);if(mode==='thermal')t.layout.width=Number(db.settings.thermalWidth)===58?58:80;else{let p=invoicePaperSizes.find(p=>p.id===supportedInvoicePaper(db.settings.invoicePaperSize));t.layout.width=p.width;t.layout.height=p.height}return t};
const templateFormBeforePaperSync=templateDesignerForm;
templateDesignerForm=function(t){return templateFormBeforePaperSync(t).replace('<form id="invoiceTemplateForm">','<form id="invoiceTemplateForm">'+designerPaperChoice(t.mode,t.layout))};
const layoutFormBeforePaperSync=layoutFormMarkup;
layoutFormMarkup=function(p,mode){return layoutFormBeforePaperSync(p,mode).replace('<form id="customLayoutForm">','<form id="customLayoutForm">'+designerPaperChoice(mode,p))};
const openTemplateBeforePaperSync=openInvoiceTemplateDesigner;
openInvoiceTemplateDesigner=function(mode='regular',templateId){let hinted=mode==='thermal'?$('#thermalPaperWidth')?.value:$('#invoicePaperChoice')?.value;openTemplateBeforePaperSync(mode,templateId);let selector=$('#invoiceTemplateForm [data-designer-paper]');if(selector&&!templateId&&hinted){selector.value=hinted;selector.dispatchEvent(new Event('change',{bubbles:true}))}};
document.addEventListener('change',e=>{let mode=e.target.dataset.designerPaper;if(!mode)return;let form=e.target.closest('form'),width,height;if(mode==='thermal')width=Number(e.target.value);else{let p=invoicePaperSizes.find(p=>p.id===e.target.value);if(!p)return;width=p.width;height=p.height}let w=form.querySelector('[name="width"]'),h=form.querySelector('[name="height"]');if(w)w.value=width;if(h&&height)h.value=height;let margin=form.querySelector('[name="margin"]');if(margin&&Number(margin.value)>width/4)margin.value=Math.min(10,width/4)},true);
document.addEventListener('input',e=>{if(!['width','height'].includes(e.target.name))return;let form=e.target.closest('#invoiceTemplateForm,#customLayoutForm'),select=form?.querySelector('[data-designer-paper]');if(!select)return;let width=Number(form.querySelector('[name="width"]').value),height=Number(form.querySelector('[name="height"]')?.value),sizes=select.dataset.designerPaper==='thermal'?[{id:'58',width:58},{id:'80',width:80}]:invoicePaperSizes;let p=sizes.find(p=>Math.abs(p.width-width)<0.2&&(!p.height||Math.abs(p.height-height)<0.2));if(p)select.value=p.id},true);
const applyTemplateBeforePaperSync=applyDesignedTemplate;
applyDesignedTemplate=function(sheet,t){applyTemplateBeforePaperSync(sheet,t);if(!sheet||!t)return;if(t.mode==='regular'){let p=invoicePaperSizes.find(p=>Math.abs(p.width-t.layout.width)<0.2&&Math.abs(p.height-t.layout.height)<0.2);sheet.dataset.paper=p?.id||'Custom';sheet.classList.toggle('smallInvoicePaper',t.layout.width<=176)}sheet.dataset.designerPaperWidth=t.layout.width;sheet.dataset.designerPaperHeight=t.mode==='thermal'?'auto':t.layout.height};
render();
const openLayoutBeforePaperSync=openLayoutDesigner;
openLayoutDesigner=function(mode,key,id){let hinted=mode==='thermal'?$('#thermalPaperWidth')?.value:$('#invoicePaperChoice')?.value;let stored=db.settings.invoiceLayouts?.[mode];openLayoutBeforePaperSync(mode,key,id);let selector=$('#customLayoutForm [data-designer-paper]');if(selector&&!stored?.enabled){selector.value=hinted||(mode==='thermal'?String(Number(db.settings.thermalWidth)===58?58:80):supportedInvoicePaper(db.settings.invoicePaperSize));selector.dispatchEvent(new Event('change',{bubbles:true}))}};
